public class ArrowPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            ArrowPainter.paint(g, width, height);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(90, 60);
            java.awt.image.BufferedImage b = render(60, 60);
            check("shaft body (30,30)", "#000000", pixel(a, 30, 30));
            check("white above the shaft (30,10)", "#FFFFFF", pixel(a, 30, 10));
            check("head centre (70,30)", "#000000", pixel(a, 70, 30));
            check("near the tip (82,30)", "#000000", pixel(a, 82, 30));
            check("white above the head slope (80,10)", "#FFFFFF", pixel(a, 80, 10));
            check("shaft reaches the left edge (5,30)", "#000000", pixel(a, 5, 30));
            check("white below the shaft (5,50)", "#FFFFFF", pixel(a, 5, 50));
            check("square image shaft (20,30)", "#000000", pixel(b, 20, 30));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

