import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;

public class ArrowPainter {

    public static void paint(Graphics2D g, int width, int height) {
        g.setColor(Color.WHITE);
        g.fillRect(0, 0, width, height);

        int midY = height / 2;
        int shaftHalf = height / 6;
        int headWidth = width / 3;
        int headX = width - headWidth;

        Polygon arrow = new Polygon();
        arrow.addPoint(0, midY - shaftHalf);
        arrow.addPoint(headX, midY - shaftHalf);
        arrow.addPoint(headX, 0);
        arrow.addPoint(width - 1, midY);
        arrow.addPoint(headX, height - 1);
        arrow.addPoint(headX, midY + shaftHalf);
        arrow.addPoint(0, midY + shaftHalf);

        g.setColor(Color.BLACK);
        g.fillPolygon(arrow);
    }
}
